#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + K_THREAD_STACK_SIZEOF(128))
#define THREAD_PRIORITY K_PRIO_PREEMPT(10)

struct data_item {
	void *fifo_reserved; /* 1st word reserved for use by k_fifo */
	uint32_t value;
	uint32_t id;
};

/* FIFOs for testing */
struct k_fifo fifo1;
struct k_fifo fifo2;

/* Thread stacks and data */
static K_THREAD_STACK_DEFINE(producer_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(consumer_stack, STACK_SIZE);
static struct k_thread producer_thread_data;
static struct k_thread consumer_thread_data;

/* Data items for testing */
static struct data_item item_a = {.value = 0xAAAAAAAA, .id = 1};
static struct data_item item_b = {.value = 0xBBBBBBBB, .id = 2};
static struct data_item item_c = {.value = 0xCCCCCCCC, .id = 3};
static struct data_item item_d = {.value = 0xDDDDDDDD, .id = 4};

/* Producer thread */
void producer_thread(void *p1, void *p2, void *p3)
{
	struct k_fifo *fifo = (struct k_fifo *)p1;
	struct data_item *item = (struct data_item *)p2;

	k_fifo_put(fifo, item);
	k_msleep(10); /* Give consumer a chance to run */
}

/* Consumer thread */
void consumer_thread(void *p1, void *p2, void *p3)
{
	struct k_fifo *fifo = (struct k_fifo *)p1;
	struct data_item *expected_item = (struct data_item *)p2;
	struct data_item *received_item;

	received_item = k_fifo_get(fifo, K_FOREVER);
	zassert_equal_ptr(received_item, expected_item, "Received item pointer mismatch");
	zassert_equal(received_item->value, expected_item->value, "Received item value mismatch");
	zassert_equal(received_item->id, expected_item->id, "Received item ID mismatch");
}

ZTEST_SUITE(fifo_usage, NULL, NULL, NULL, NULL, NULL);

/* Test 1: Basic put/get */
ZTEST_USER_F(fifo_usage, test_fifo_put_get)
{
	k_fifo_init(&fifo1);
	k_fifo_put(&fifo1, &item_a);
	struct data_item *received_item = k_fifo_get(&fifo1, K_NO_WAIT);
	zassert_equal_ptr(received_item, &item_a, "Item A not retrieved");
	zassert_equal(received_item->value, item_a.value, "Item A value mismatch");
}

/* Test 2: Multiple items */
ZTEST_USER_F(fifo_usage, test_fifo_multiple_items)
{
	k_fifo_init(&fifo1);
	k_fifo_put(&fifo1, &item_a);
	k_fifo_put(&fifo1, &item_b);

	struct data_item *received_item = k_fifo_get(&fifo1, K_NO_WAIT);
	zassert_equal_ptr(received_item, &item_a, "Item A not retrieved first");
	received_item = k_fifo_get(&fifo1, K_NO_WAIT);
	zassert_equal_ptr(received_item, &item_b, "Item B not retrieved second");
}

/* Test 3: FIFO with threads */
ZTEST_USER_F(fifo_usage, test_fifo_threads)
{
	k_fifo_init(&fifo1);

	k_thread_create(&producer_thread_data, producer_stack, STACK_SIZE,
					producer_thread, &fifo1, &item_c, NULL,
					THREAD_PRIORITY, 0, K_NO_WAIT);

	k_thread_create(&consumer_thread_data, consumer_stack, STACK_SIZE,
					consumer_thread, &fifo1, &item_c, NULL,
					THREAD_PRIORITY, 0, K_NO_WAIT);

	k_thread_join(&consumer_thread_data, K_FOREVER);
	k_thread_join(&producer_thread_data, K_FOREVER);
}

/* Test 4: Multiple FIFOs */
ZTEST_USER_F(fifo_usage, test_fifo_multiple_fifos)
{
	k_fifo_init(&fifo1);
	k_fifo_init(&fifo2);

	k_fifo_put(&fifo1, &item_a);
	k_fifo_put(&fifo2, &item_b);

	struct data_item *received_item_1 = k_fifo_get(&fifo1, K_NO_WAIT);
	struct data_item *received_item_2 = k_fifo_get(&fifo2, K_NO_WAIT);

	zassert_equal_ptr(received_item_1, &item_a, "Item A not retrieved from fifo1");
	zassert_equal_ptr(received_item_2, &item_b, "Item B not retrieved from fifo2");
}

/* Test 5: FIFO get_peek */
ZTEST_USER_F(fifo_usage, test_fifo_get_peek)
{
	k_fifo_init(&fifo1);
	k_fifo_put(&fifo1, &item_a);
	k_fifo_put(&fifo1, &item_b);

	struct data_item *peeked_item = k_fifo_get_peek(&fifo1);
	zassert_equal_ptr(peeked_item, &item_a, "Peeked item A mismatch");

	struct data_item *received_item = k_fifo_get(&fifo1, K_NO_WAIT);
	zassert_equal_ptr(received_item, &item_a, "Retrieved item A mismatch");

	peeked_item = k_fifo_get_peek(&fifo1);
	zassert_equal_ptr(peeked_item, &item_b, "Peeked item B mismatch");

	received_item = k_fifo_get(&fifo1, K_NO_WAIT);
	zassert_equal_ptr(received_item, &item_b, "Retrieved item B mismatch");

	peeked_item = k_fifo_get_peek(&fifo1);
	zassert_is_null(peeked_item, "FIFO should be empty after all gets");
}
